from typing import Annotated
from fastapi import Depends, FastAPI, Response
from fastapi.testclient import TestClient

app = FastClient = FastAPI()

def modify_response() -> Response:
    resp = Response(status_code=204)
    resp.headers['X-Custom'] = 'custom-value'
    return resp

@app.get('/annotated')
def endpoint_annotated(response: Annotated[Response, Depends(modify_response)]):
    return response

@app.get('/default')
def endpoint_default(response: Response = Depends(modify_response)):
    return response

@app.get('/regular')
def endpoint_regular(response: Response):
    response.headers['X-Custom'] = 'regular-value'
    return {'msg': 'regular'}

client = TestClient(app)
r = client.get('/annotated'); print('annotated', r.status_code, r.headers.get('x-custom'))
r = client.get('/default'); print('default', r.status_code, r.headers.get('x-custom'))
r = client.get('/regular'); print('regular', r.status_code, r.headers.get('x-custom'), r.json())
""}

